// mountPrefix returns the part of the routing path that precedes routePath, which is
// the RoutePath of a mounted sub-router. It returns "" if routePath is not a suffix
// of the routing path. The routing path is RawPath when set, matching chi's routing.
func mountPrefix(r *http.Request, routePath string) string {
	p := r.URL.Path
	if r.URL.RawPath != "" {
		p = r.URL.RawPath
	}
	if !strings.HasSuffix(p, routePath) {
		return ""
	}
	return p[:len(p)-len(routePath)]
}
